#!/usr/bin/env python3
"""Observe real Reader XFDF import event order while preserving original actions.

A combined input is generated by the native export API. Logging wraps existing
K/V/F on two target fields and C on Str Mod, catches getter errors locally, and
restores original action code before saving. Isolated diagnostics, not a full
character-import pass. No expected reference values are written with a library.
"""
import argparse, hashlib, importlib.util, json, shutil, subprocess, sys, time
from pathlib import Path
from pypdf import PdfReader
ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'tools/acrobat'))
import control as c
from verify import canonical_fields, field_text, script_hashes, inspect
spec = importlib.util.spec_from_file_location('interop', ROOT / 'tools/native/reader-xfdf-import.py')
interop = importlib.util.module_from_spec(spec); spec.loader.exec_module(interop)


def actions(source, empty_controls=False):
    reader = PdfReader(source); fields = canonical_fields(reader); result = {}
    for name, triggers in ([('Hair colour', ['K','V','F']), ('Attack.1.Weapon Selection', ['K','V','F']), ('Str Mod', ['C'])] if empty_controls else [('Player Name', ['K', 'V', 'F']), ('Notes.Left', ['K', 'V', 'F']), ('Str Mod', ['C'])]):
        node = reader.get_object(fields[name]['reference']); aa = node.get('/AA', {})
        if hasattr(aa, 'get_object'): aa = aa.get_object()
        result[name] = {key: field_text(aa['/' + key].get_object().get('/JS', '')) if '/' + key in aa else '' for key in triggers}
    return result


def main():
    p = argparse.ArgumentParser(description=__doc__); p.add_argument('--native', type=Path, required=True); p.add_argument('--readiness', type=Path, required=True); p.add_argument('--blank-targets', action='store_true'); p.add_argument('--empty-controls',action='store_true');p.add_argument('--original-wrapper',action='store_true');p.add_argument('--fixture',choices=['2024','2014','ashnar'],default='2024'); args = p.parse_args()
    native = json.loads(args.native.read_text()); assert native['passed']; reference = json.loads(Path(native['reader']).read_text()); source = Path(reference['input'])
    if args.fixture!='2024':source=next((ROOT/'Testing').glob('*_2014_*.pdf' if args.fixture=='2014' else '*Ashnar*.pdf'))
    ready = json.loads(args.readiness.read_text()); assert ready['passed'] and len(ready['cases']) == 24 and ready['harness_sha256'] == c.harness_fingerprint()
    folder = ROOT / 'output/testing' / ('reader-xfdf-events-' + str(time.time_ns())); folder.mkdir(); print(folder, flush=True)
    binary = folder / 'mpmb-reader'; shutil.copy2(ROOT / 'target/debug/mpmb-reader', binary)
    report = {'passed': False, 'scope': __doc__, 'source': str(source), 'source_sha256': hashlib.sha256(source.read_bytes()).hexdigest(), 'native': str(args.native.resolve()), 'binary_sha256': hashlib.sha256(binary.read_bytes()).hexdigest(), 'file_dialogs': [], 'blank_targets': args.blank_targets,'fixture':args.fixture}; opened = False; pending = None
    remote = c.remote_path('runs/xfdf-events-' + str(time.time_ns()) + '.pdf'); remote_xml = remote[:-4] + '.xfdf'
    try:
        scenario = {'dialogs': [{'result': 'ok'}] * 10, 'alerts': [1] * 20, 'steps': [{'op': 'advance', 'ms': 4100}, {'op': 'eval', 'code': "exportAsXFDFStr({aFields:['Player Name','Notes.Left'],cHRef:'urn:mpmb:qualification'})"}]}
        if args.empty_controls:
            scenario['steps'][-1]['code']="getField('Hair colour').value='';getField('Attack.1.Weapon Selection').value='';exportAsXFDFStr({aFields:['Hair colour','Attack.1.Weapon Selection'],bAllFields:true,cHRef:'urn:mpmb:qualification'})"
            report['empty_controls']=True
        (folder / 'input-scenario.json').write_text(json.dumps(scenario))
        with (folder / 'input.log').open('w') as log: result = subprocess.run([str(binary), str(args.native.parent / 'native.pdf'), '--probe', str(folder / 'input-scenario.json'), str(folder / 'input-probe.json')], stdout=log, stderr=log, timeout=300)
        generated = json.loads((folder / 'input-probe.json').read_text()); assert result.returncode == 0 and generated['passed']; xml = generated['stages'][-1]['result']; (folder / 'input.xfdf').write_text(xml, encoding='utf-8'); report['input_sha256'] = hashlib.sha256(xml.encode()).hexdigest()
        original = actions(source,args.empty_controls)
        if not args.empty_controls:
            assert original['Notes.Left']['V'] == 'correctRichTextLineSpacing();'
            assert original['Notes.Left']['F'] == 'formatRichText();'
        assert original['Str Mod']['C']
        if args.empty_controls: assert original['Attack.1.Weapon Selection']['V']
        report['original_action_sha256'] = {name: {key: hashlib.sha256(code.encode()).hexdigest() for key, code in entries.items()} for name, entries in original.items()}
        definitions = json.dumps(original, ensure_ascii=True)
        observer = r"""var iFileName='XFDF original-action event observer.js';Value('User Script','');(function(d){var original=ORIGINAL,trace=[],r={trace:[],fields:[],errors:[],sentinel:'\u00a0\u2028\ud83d\ude00'},kinds={K:'Keystroke',V:'Validate',F:'Format',C:'Calculate'};function read(fn){try{return fn()}catch(e){return {getterError:e.name,message:String(e)}}}d.__xfdfEventObserve=function(phase,e){trace.push({phase:phase,target:read(function(){return e.target.name}),name:read(function(){return e.name}),value:read(function(){return e.value}),rich:read(function(){return JSON.parse(JSON.stringify(e.richValue))}),richDirect:read(function(){var v=e.richValue;return v?v.map(function(span){return {text:span.text,spacingType:typeof span.linespacing,spacing:span.linespacing,spacingOwn:Object.prototype.hasOwnProperty.call(span,'linespacing')}}):v}),targetRichText:read(function(){return e.target.richText}),source:read(function(){return e.source&&e.source.name}),stored:read(function(){return {player:d.getField('Player Name').valueAsString,notes:d.getField('Notes.Left').valueAsString}})})};var appBefore=app.calculate,docBefore=d.calculate;app.calculate=false;d.calculate=false;try{d.getField('Player Name').value='old player';d.getField('Notes.Left').value=SEED_NOTES;Object.keys(original).forEach(function(name){var f=d.getField(name);Object.keys(original[name]).forEach(function(key){f.setAction(kinds[key],'__xfdfEventObserve('+JSON.stringify(key+'-before')+',event);\n'+original[name][key]+'\n;__xfdfEventObserve('+JSON.stringify(key+'-after')+',event);')})});app.calculate=appBefore;d.calculate=docBefore;if(appBefore&&docBefore)d.calculateNow();trace=[];d.importAnXFDF();r.trace=trace.slice(0);['Player Name','Notes.Left'].forEach(function(name){var f=d.getField(name);r.fields.push({field:name,value:f.valueAsString,richText:f.richText,richValue:f.richText?f.richValue:null,richDirect:f.richText?f.richValue.map(function(span){return {text:span.text,spacingType:typeof span.linespacing,spacing:span.linespacing,spacingOwn:Object.prototype.hasOwnProperty.call(span,'linespacing')}}):null})})}catch(e){r.errors.push({name:e.name,message:e.message})}finally{Object.keys(original).forEach(function(name){var f=d.getField(name);Object.keys(original[name]).forEach(function(key){f.setAction(kinds[key],original[name][key])})});app.calculate=appBefore;d.calculate=docBefore}Value('PC Name',JSON.stringify(r).replace(/[\u007f-\uffff]/g,function(ch){return '\\u'+('0000'+ch.charCodeAt(0).toString(16)).slice(-4)}));})(tDoc);""".replace('ORIGINAL', definitions).replace('SEED_NOTES', json.dumps('' if args.blank_targets else 'old notes'))
        if args.empty_controls:
            observer=observer.replace("'Player Name'","'Hair colour'").replace("'Notes.Left'","'Attack.1.Weapon Selection'").replace('"old notes"','"Quarterstaff"')
            observer=observer.replace('if(appBefore&&docBefore)d.calculateNow();trace=[];', 'if(appBefore&&docBefore){if(calcStartSet)calcCont(true);else d.calculateNow();}trace=[];')
            start=observer.index(',rich:read(');end=observer.index(',source:read(',start)
            observer=observer[:start]+observer[end:]
            start=observer.index(',richText:f.richText');end=observer.index('})})}catch',start)
            observer=observer[:start]+observer[end:]
            report['comparison_scope']='Choice/text value, event order, source and stored state; rich API getter availability excluded and remains a host coverage gap.'
        if args.original_wrapper:
            assert not args.empty_controls
            observer=observer.replace('d.importAnXFDF();',"Import('xfdf');")
            report['original_wrapper']=True
        (folder / 'observer.js').write_text(observer); report['observer_sha256'] = hashlib.sha256(observer.encode()).hexdigest()
        with c.desktop_lock():
            assert not [e for e in c.command('inspect') if e.get('class') == 'AcrobatSDIWindow' and '.pdf' in e.get('name', '').lower()], 'Pre-existing Reader document'
            for local, path in [(source, remote), (folder / 'input.xfdf', remote_xml)]: subprocess.run(c.SCP + [str(local), c.SCP_TARGET + ':MPMB-Testing/runs/' + path.replace('\\', '/').split('/')[-1]], check=True, capture_output=True)
            assert c.powershell('(Get-FileHash -Algorithm SHA256 ' + c.literal(remote_xml) + ').Hash').strip().lower() == report['input_sha256']
            opened = True; c.ensure_document(remote); c.script('set', path=remote, values={'User Script': observer}); pending = c.script_submit('call', path=remote, name='RunUserScript', args=[False]); report['request'] = pending
            if args.original_wrapper:
                from spells import wait_dialog
                root,elements=wait_dialog('Is everything ready for importing?',time.monotonic()+40)
                offered=[e for e in elements if e.get('owner')==root['handle'] and e.get('class')=='Button' and e.get('name','').replace('&','')=='Yes'];assert len(offered)==1
                report['confirmation']={'observed':elements,'invoke':c.command('invoke',name=offered[0]['name'],owner=root['handle'])}
            interop.file_dialog(remote_xml, remote, report['file_dialogs'])
            if args.original_wrapper:
                deadline=time.monotonic()+15
                while time.monotonic()<deadline:
                    elements=c.command('inspect');roots=[e for e in elements if e.get('class')=='#32770' and e.get('name')=='Notes on Importing']
                    if roots:
                        assert len(roots)==1;buttons=[e for e in elements if e.get('owner')==roots[0]['handle'] and e.get('class')=='Button' and e.get('name')=='OK'];assert len(buttons)==1
                        report['import_summary']={'observed':elements,'invoke':c.command('invoke',name='OK',owner=roots[0]['handle'])};break
                    time.sleep(.2)
            report['completion'] = c.script_result(pending, timeout=90); pending = None
            summary = c.script('field_summary', path=remote, fields=['PC Name'])['fields']['PC Name']; report['summary'] = summary
            c.script('set', path=remote, values={'User Script': ''}); saved = remote[:-4] + '-saved.pdf'; c.script('save', path=remote, output=saved); remote = saved; report['close'] = c.script('close', path=remote); opened = False
            local = c.fetch(remote, folder / 'reader.pdf'); report['captured'] = interop.xfdf.style.saved_capture(local, summary, source); assert not report['captured']['errors']; assert actions(local,args.empty_controls) == original
            report['independent']=inspect(local,{item['field']:item['value'] for item in report['captured']['fields']});assert report['independent']['passed']
            assert script_hashes(local) == script_hashes(source) and hashlib.sha256(source.read_bytes()).hexdigest() == report['source_sha256']; report['passed'] = True
    except Exception as error: report['error'] = str(error); raise
    finally:
        if opened:
            try:
                with c.desktop_lock():
                    shot = c.command('screenshot'); c.fetch(shot['path'], folder / 'failure.png')
                    if pending: report['original_completion'] = c.script_result(pending, timeout=25)
                    retained = remote[:-4] + '-failed-retained.pdf'; c.script('save', path=remote, output=retained); report['cleanup_close'] = c.script('close', path=retained); c.fetch(retained, folder / 'failed-retained.pdf')
            except Exception as error: report['cleanup_error'] = str(error)
        (folder / 'events.json').write_text(json.dumps(report, indent=2) + '\n'); print(folder / 'events.json', flush=True)


if __name__ == '__main__': main()
